  const span = size === 'large' ? 2147483648 : 4 + pick(6);
  const value = () => Math.max(-2147483648, Math.min(2147483647, pick(2 * span + 1) - span));
  if (rand() < 0.5) return [Array.from({ length: n }, value)];
