  // unless a final random value is appended.
  const runA = Array.from({ length: n }, value).sort((a, b) => b - a);
  const runB = Array.from({ length: n }, value).sort((a, b) => b - a);
  const nums = [];
  let a = 0;
  let b = 0;
  while (nums.length < n) nums.push(rand() < 0.5 ? runA[a++] : runB[b++]);
  if (rand() < 0.3) nums[n - 1] = value();
